from qiskit import QuantumCircuit
import math

def solve(n: int, L: int) -> QuantumCircuit:
    qc = QuantumCircuit(n)
    # global phase is irrelevant
    if L <= 0 or L >= 2 ** n:
        return qc

    target = n - 1
    controls = list(range(n - 1))

    for i in range(L):
        # map |i> to |11..1>
        for j in range(n):
            if ((i >> j) & 1) == 0:
                qc.x(j)

        if n == 1:
            qc.z(0)
        else:
            qc.mcphase(math.pi, controls, target)

        # unmap
        for j in range(n):
            if ((i >> j) & 1) == 0:
                qc.x(j)

    return qc

from qiskit import QuantumCircuit
import math

def solve(n: int, L: int) -> QuantumCircuit:
    qc = QuantumCircuit(n)
    size = 1 << n
    if L <= 0 or L >= size:
        # empty or global phase
        return qc

    for k in range(n):
        if ((L >> k) & 1) == 0:
            continue

        # make x_k = 0 correspond to target = 1
        qc.x(k)

        control_qubits = []
        # higher bits j>k must equal L_j
        for j in range(k + 1, n):
            if ((L >> j) & 1) == 0:
                qc.x(j)                 # turn 0-control into 1-control
            control_qubits.append(j)

        if control_qubits:
            qc.mcp(math.pi, control_qubits, k)
        else:
            qc.p(math.pi, k)            # Z on k

        # undo the X on the higher bits
        for j in range(k + 1, n):
            if ((L >> j) & 1) == 0:
                qc.x(j)

        qc.x(k)                         # undo target flip

    return qc
